```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = crate::wasi::clocks::wall_clock::now().seconds;

        let fetched = match crate::aap::caps::http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", seconds, fetched);
        let notified = crate::aap::caps::notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations requests. The node's `with` clause grants only the HTTP client (scoped to `feeds.example.com`), the notifier, and the wall clock. Writing to `/var/log/aap/node-inputs.log` needs a filesystem capability this node doesn't have. Fetching `metadata.internal.example` would be refused at the boundary as an out-of-scope request, and building that URL from the input text would send feed content to a host outside the grant. If operations needs either behaviour, it should be granted through the node's `with` clause and the graph, not added in the body.

